  ${b.statusButtons ? `<div style="margin-top:4px">${btn(mailto(to, 'APPLIED', c.jrId, 'applied'), '✅ I applied')}${btn(mailto(to, 'SKIP', c.jrId, 'skipped'), '⏭ Skip')}</div>` : ''}
</div></div></body></html>`;
  return { subject, html, text: `${subject}\n\n${job.url}\n` };
}

// 🩺 Source health — tell me (once a day per source) when a board or company link is broken
const plan = $('⚙️ Plan run').all();
const resp = $input.all();
const state = $getWorkflowStaticData('global');
state.health = state.health || {};
const now = Date.now();
const bad = [];
const FAIL_RUNS = 3; // consecutive failed runs before a source counts as broken
const invalid = plan[0].json._candidate.leads ? [] : (plan[0].json._candidate.invalidCompanies || []);
for (const u of invalid) {
  const key = 'url:' + u;
  if (!state.health[key] || now - state.health[key] > 864e5) { bad.push({ name: u, problem: "can't tell which job board this careers link uses — paste the link of the page that lists the jobs" }); state.health[key] = now; }
}
for (let i = 0; i < resp.length; i++) {
  const req = plan[i] && plan[i].json;
  if (!req || req.source === 'none' || req.manualUrl || req.lead) continue; // a pasted link / LinkedIn lead lookup isn't a source to monitor
  const r = resp[i].json;
  let problem = null;
  if (r.error) problem = (r.error.message || JSON.stringify(r.error)).slice(0, 140);
  else {
    const d = parseBody(r.data);
    if (d === null || d === '') problem = 'empty response';
    else if (req.slug && req.source !== 'himalayas' && req.source !== 'personio' && typeof d === 'object' && !Array.isArray(d) && !d.jobs && !d.offers && !d.content && !d.result && !d.data) problem = 'unexpected response — wrong company link?';
    else if (d && d.error && req.source === 'hiringcafe_mcp') problem = 'Hiring Cafe MCP error: ' + JSON.stringify(d.error).slice(0, 100);
    else if (d && d.result && d.result.isError) { // MCP tools report failures inside a normal 200 reply
      const msg = [].concat(d.result.content || []).map((c) => c && c.text).filter(Boolean).join(' ');
      problem = 'returned an error: ' + (msg || 'no details').slice(0, 120);
    } else if (!req.company) {
      // job boards (not company pages, which can legitimately have no openings): zero usable jobs for a day = broken
      let count = 0; try { count = normalize(req, r.data).length; } catch (e) {}
      state.yield = state.yield || {};
      const y = state.yield[req.source + ':' + (req.slug || '')] = state.yield[req.source + ':' + (req.slug || '')] || { since: now, last: null };
      if (count > 0) y.last = now;
      else if (now - (y.last || y.since) > 864e5) problem = 'no usable jobs for over 24 hours — the source may have changed or be blocking us';
    }
  }
  const key = req.source + ':' + (req.slug || '');
  // Boards hiccup (a 503 or a stray 404 that's gone 15 minutes later). Only speak up after FAIL_RUNS failed runs in a row.
  state.healthFails = state.healthFails || {};
  if (problem) {
    const fails = state.healthFails[key] = (state.healthFails[key] || 0) + 1;
    if (fails >= FAIL_RUNS && (!state.health[key] || now - state.health[key] > 864e5)) { bad.push({ name: req.company || req.source, problem, src: req.source }); state.health[key] = now; }
  } else {
    delete state.healthFails[key];
    if (state.health[key]) delete state.health[key];
  }
}
await postStatus(this.helpers, 'health', { run: $execution.id, problems: bad.map((b) => ({ name: b.name + (b.src ? ' (' + b.src + ')' : ''), problem: b.problem })) });
if (!bad.length) return [];
const lines = bad.map((b) => `• ${b.name}${b.src ? ' (' + b.src + ')' : ''}: ${b.problem}`);
const text = `JobRadar source check — these sources failed ${FAIL_RUNS} runs in a row, so it's not a one-off hiccup. Fix or switch them off in settings.json:\n\n${lines.join('\n')}`;
return [
  { json: { kind: 'tg_text', tg: { text: '🩺 ' + text, disable_web_page_preview: true } } },
  { json: { kind: 'email', subject: 'JobRadar: some sources need attention', text, html: `<pre style="font-family:inherit;white-space:pre-wrap">${escHtml(text)}</pre>` } },
];

// ───── helpers (generated from src/lib — edit there and rebuild) ─────
// ---- util.js : small shared helpers (inlined into n8n Code nodes) ----

function decodeEntities(s) {
  if (!s) return '';
  let out = String(s);
  // Greenhouse double-escapes (&amp;lt;) so decode twice
  for (let i = 0; i < 2; i++) {
    out = out
      .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
      .replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
      .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
      .replace(/&amp;/g, '&');
  }
  return out;
}

function htmlToText(html) {
  if (!html) return '';
  return decodeEntities(String(html))
    .replace(/<\s*(br|\/p|\/div|\/li|\/h\d|\/tr)\s*\/?>/gi, '\n')
    .replace(/<\s*li[^>]*>/gi, '\n• ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

function escHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function slugify(s, max) {
  const out = String(s || '')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return out.slice(0, max || 60);
}

function toIso(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    const ms = v < 1e12 ? v * 1000 : v; // seconds vs ms
    const d = new Date(ms);
    return isNaN(d) ? null : d.toISOString();
  }
  let s = String(v).trim();
  if (/^\d{10,13}$/.test(s)) return toIso(Number(s));
  if (/^\d{4}-\d\d-\d\d \d/.test(s)) s = s.replace(' ', 'T');
  if (/^\d{4}-\d\d-\d\dT\d\d:\d\d(:\d\d(\.\d+)?)?$/.test(s)) s += 'Z'; // no timezone → assume UTC
  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString();
}

function hoursSince(iso, now) {
  if (!iso) return null;
  return ((now || Date.now()) - new Date(iso).getTime()) / 36e5;
}

function humanAge(iso, now) {
  const h = hoursSince(iso, now);
  if (h === null) return 'post time unknown';
  if (h < 1) return Math.max(1, Math.round(h * 60)) + ' min ago';
  if (h < 48) return Math.round(h) + ' h ago';
  return Math.round(h / 24) + ' days ago';
}

function stripHtmlComments(md) {
  return String(md || '').replace(/<!--[\s\S]*?-->/g, '').replace(/^\s+/, '');
}

function extractHtmlComments(md) {
  const out = [];
  String(md || '').replace(/<!--([\s\S]*?)-->/g, (_, c) => { out.push(c.trim()); return ''; });
  return out.join('\n\n');
}

function truncate(s, n) {
  s = String(s || '');
  return s.length > n ? s.slice(0, n) + ' …[truncated]' : s;
}

function jobradarDir() {
  try { return (typeof $env !== 'undefined' && $env.JOBRADAR_DIR) || '/home/node/jobradar'; } catch (e) { return '/home/node/jobradar'; }
}

function envGet(k) {
  try { return (typeof $env !== 'undefined' && $env[k]) || undefined; } catch (e) { return undefined; }
}

function channelsEnabled() {
  return String(envGet('NOTIFY_CHANNELS') || 'telegram').toLowerCase().split(/[\s,]+/).filter(Boolean);
}

function shortHash(s) {
  let h = 0x811c9dc5;
  for (const ch of String(s)) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(36).toUpperCase().padStart(6, '0').slice(-6);
}

function fillCoverLetter(base, slots) {
  let txt = stripHtmlComments(base);
  for (const k of Object.keys(slots)) txt = txt.split('{{' + k + '}}').join(String(slots[k] || '').trim());
  return txt.replace(/\n{3,}/g, '\n\n').trim() + '\n';
}

function trackerRow(job, fit, extra) {
  const num = (v) => (v === null || v === undefined || isNaN(Number(v)) ? -1 : Number(v));
  return Object.assign({
    jr_id: 'JR-' + shortHash(job.uid), uid: job.uid, alt_key: job.altKey, company: job.company, title: job.title, location: String(job.location || '').slice(0, 200),
    source: job.source, url: job.url || '', apply_url: job.applyUrl || job.url || '', score: num(fit.score), skills_fit: num(fit.skills_fit), values_fit: num(fit.values_fit),
    values_note: String((fit.values_match || []).join(' · ') || fit.company_note || '').slice(0, 300),
    dream: !!job.dream, role_family: fit.role_family || '', salary: job.salary ? String(job.salary).slice(0, 120) : '',
    posted_at: job.postedAt || '', minutes_to_alert: job.postedAt ? Math.max(0, Math.round((Date.now() - new Date(job.postedAt)) / 60000)) : -1,
    applied_at: '', outcome: '', outcome_at: '',
  }, extra || {});
}

// Companies you'd relocate for: settings.companies[].relocateTo = ["United Kingdom", "Ireland"]. Does that cover a country?
function relocateCovers(relocateTo, country) {
  if (!Array.isArray(relocateTo) || !country) return false;
  const alias = { uk: 'united kingdom|uk|england|scotland|wales|britain|great britain', us: 'united states|usa|us|u\\.s\\.', ie: 'ireland|irish' };
  const norm = (s) => String(s).toLowerCase().trim();
  const group = (s) => { const n = norm(s); for (const g of Object.values(alias)) if (new RegExp('^(' + g + ')$').test(n)) return g; return n; };
  return relocateTo.some((r) => group(r) === group(country));
}

// Postings that only hire in one country, whatever the board's location label says.
// Returns { country, evidence } or null. Conservative: needs an explicit signal, not just a US city.
function countryLock(text, profileMd) {
  const t = String(text || '');
  // The candidate's own one-line "who I am" (first line under the first heading of the search profile).
  const who = (String(profileMd || '').replace(/<!--[\s\S]*?-->/g, '').match(/^#[^\n]*\n+([^\n#]+)/m) || [, ''])[1];
  const livesIn = { US: /\b(United States|USA|U\.S\.|US-based|based in the US)\b/i, UK: /\b(United Kingdom|UK|London|England|Scotland)\b/, Canada: /\bCanada\b/i };
  const rules = [
    ['US', /(geographic(al)? pay zones?|pay zones?)[\s\S]{0,400}?(United States|U\.S\.|US locations)/i],
    ['US', /all other U\.?S\.? (locations|cities|metro)/i],
    ['US', /(must|need to|required to) (be )?(legally )?(authori[sz]ed|eligible) to work in the (United States|U\.S\.?|US)\b/i],
    ['US', /(must|need to) (reside|live|be based) in the (United States|U\.S\.?|US)\b/i],
    ['US', /\b401\(?k\)?/i],
    ['UK', /(must have|require[sd]?) (the )?(full )?right to work in the (UK|United Kingdom)/i],
    ['Canada', /(must|need to) (reside|live|be based) in Canada/i],
  ];
  for (const [country, re] of rules) {
    const m = t.match(re);
    if (m && !(livesIn[country] && livesIn[country].test(who))) return { country, evidence: '"' + m[0].replace(/\s+/g, ' ').slice(0, 80) + '"' };
  }
  return null;
}

// Tell the helper service what this run did, so the chat can answer "why so quiet?". Never fails the run.
async function postStatus(helpers, part, data) {
  try {
    if (!helpers || !helpers.httpRequest) return;
    const base = envGet('RENDERER_URL') || 'http://renderer:3100';
    await helpers.httpRequest({ method: 'POST', url: base + '/status', json: true, body: Object.assign({ part }, data), timeout: 5000 });
  } catch (e) { /* status is best-effort */ }
}

// ---- sources.js : where jobs come from + normalisation to one schema ----
// Every fetch item: { source, company, slug, dream, url, method, body }
// Every normalised job: { uid, altKey, source, company, title, location, remote,
//   workplaceType, postedAt, url, applyUrl, salary, description, dream, sourceLabel }

function atsUrls() { return {
  ashby: (s) => `https://api.ashbyhq.com/posting-api/job-board/${s}?includeCompensation=true`,
  greenhouse: (s) => `https://boards-api.greenhouse.io/v1/boards/${s}/jobs?content=true`,
  lever: (s) => `https://api.lever.co/v0/postings/${s}?mode=json`,
  lever_eu: (s) => `https://api.eu.lever.co/v0/postings/${s}?mode=json`,
  workable: (s) => `https://apply.workable.com/api/v1/widget/accounts/${s}?details=true`,
  recruitee: (s) => `https://${s}.recruitee.com/api/offers/`,
  personio: (s) => `https://${s}.jobs.personio.de/xml?language=en`,
  smartrecruiters: (s) => `https://api.smartrecruiters.com/v1/companies/${s}/postings?limit=100`,
  pinpoint: (s) => `https://${s}.pinpointhq.com/postings.json`,
}; }

// "https://jobs.ashbyhq.com/n8n" → { ats: 'ashby', slug: 'n8n' }. Paste career-page links; no need to know what an ATS is.
function detectAts(url) {
  const u = String(url || '').trim();
  const pats = [
    [/jobs\.ashbyhq\.com\/([^/?#]+)/i, 'ashby'],
    [/(?:job-boards|boards)\.greenhouse\.io\/(?:embed\/job_board\?for=)?([^/?#&]+)/i, 'greenhouse'],
    [/jobs\.eu\.lever\.co\/([^/?#]+)/i, 'lever_eu'],
    [/jobs\.lever\.co\/([^/?#]+)/i, 'lever'],
    [/apply\.workable\.com\/([^/?#]+)/i, 'workable'],
    [/([a-z0-9-]+)\.recruitee\.com/i, 'recruitee'],
    [/([a-z0-9-]+)\.jobs\.personio\.(?:de|com)/i, 'personio'],
    [/(?:jobs|careers)\.smartrecruiters\.com\/([^/?#]+)/i, 'smartrecruiters'],
    [/([a-z0-9-]+)\.pinpointhq\.com/i, 'pinpoint'],
  ];
  for (const [re, ats] of pats) { const m = u.match(re); if (m && m[1] && !/^(embed|jobs|api)$/i.test(m[1])) return { ats, slug: m[1] }; }
  return null;
}

function normName(s) { return String(s || '').toLowerCase().replace(/\b(inc|ltd|llc|gmbh|corp|co|technologies|hq)\b/g, '').replace(/[^a-z0-9]+/g, ''); }

// every company you name: polled directly when its job board is supported, and recognised by name on every other source
function watchList(settings, extra) {
  const map = {};
  for (const entry of settings.companies || []) {
    const e = typeof entry === 'string' ? { url: entry } : entry;
    if (e.enabled === false) continue;
    const det = e.url ? detectAts(e.url) : null;
    const name = e.name || (det && det.slug);
    const extra = Array.isArray(e.relocateTo) && e.relocateTo.length ? { relocateTo: e.relocateTo } : {};
    if (name) map[normName(name)] = Object.assign({ name, dream: !!e.dream }, extra);
    for (const alias of e.aliases || []) map[normName(alias)] = Object.assign({ name, dream: !!e.dream }, extra);
  }
  for (const w of extra || []) if (w && w.name) map[normName(w.name)] = map[normName(w.name)] || { name: w.name, dream: w.dream !== false };
  return map;
}

function companiesFromSettings(settings) {
  const out = [], invalid = [];
  for (const entry of settings.companies || []) {
    const e = typeof entry === 'string' ? { url: entry } : Object.assign({}, entry);
    if (e.enabled === false) continue;
    if (!e.url && !e.ats && e.name) continue; // watch-by-name only
    const det = e.ats && e.slug ? { ats: e.ats, slug: e.slug } : detectAts(e.url);
    if (!det) { invalid.push(e.url || JSON.stringify(e)); continue; }
    const name = e.name || (/\d/.test(det.slug) || det.slug.length <= 3 ? det.slug : det.slug.replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()));
    out.push({ name, ats: det.ats, slug: det.slug, dream: !!e.dream, relocateTo: Array.isArray(e.relocateTo) ? e.relocateTo : null });
  }
  return { companies: out, invalid };
}

function buildRequests(settings, env, now, mockBase) {
  const reqs = [];
  const { companies } = companiesFromSettings(settings);
  for (const c of companies) {
    reqs.push({ source: c.ats, company: c.name, slug: c.slug, dream: c.dream, url: atsUrls()[c.ats](c.slug), method: 'GET' });
  }
  const b = settings.boards || {};
  const queries = settings.boardQueries || ['account executive'];
  // board categories: true = sales defaults, or give the board's own category/tag (see README)
  const cat = (v, d) => (typeof v === 'string' && v.trim() ? v.trim() : d);
  if (b.weworkremotely !== false)
    reqs.push({ source: 'weworkremotely', url: `https://weworkremotely.com/categories/${cat(b.weworkremotely, 'remote-sales-and-marketing-jobs')}.rss`, method: 'GET' });
  if (b.remotive !== false)
    reqs.push({ source: 'remotive', url: `https://remotive.com/api/remote-jobs?category=${encodeURIComponent(cat(b.remotive, 'sales-business'))}&limit=150`, method: 'GET' });
  if (b.remoteok !== false)
    reqs.push({ source: 'remoteok', url: `https://remoteok.com/api?tag=${encodeURIComponent(cat(b.remoteok, 'sales'))}`, method: 'GET' });
  if (b.jobicy !== false)
    reqs.push({ source: 'jobicy', url: 'https://jobicy.com/api/v2/remote-jobs?count=100', method: 'GET' });
  if (b.himalayas !== false)
    for (const q of queries)
      reqs.push({ source: 'himalayas', slug: q, url: `https://himalayas.app/jobs/api/search?q=${encodeURIComponent(q)}&sort=recent`, method: 'GET' });

  // Hiring Cafe — no official API. Two options: the community MCP server (free, unofficial) or an Apify task (paid).
  const hc = settings.hiringCafe || {};
  const every = Math.max(15, hc.everyMinutes || 60);
  const minuteOfDay = Math.floor(((now || Date.now()) / 60000) % 1440);
  if (hc.enabled && minuteOfDay % every < 15) {
    if ((hc.via || 'mcp') === 'mcp') {
      (hc.queries || queries).forEach((q, i) => reqs.push({
        source: 'hiringcafe_mcp', slug: q, method: 'POST', url: hc.mcpUrl || 'https://hiringcafe-mcp.vercel.app/api/mcp',
        body: { jsonrpc: '2.0', id: i + 1, method: 'tools/call', params: { name: 'search_jobs', arguments: Object.assign({ query: q }, hc.location ? { location: hc.location } : {}) } },
      }));
    } else if (hc.via === 'apify' && env.APIFY_TOKEN && hc.apifyTaskId) {
      reqs.push({ source: 'hiringcafe', method: 'GET',
        url: `https://api.apify.com/v2/actor-tasks/${hc.apifyTaskId}/run-sync-get-dataset-items?token=${env.APIFY_TOKEN}&timeout=240&format=json&clean=true` });
    }
  }
  if (mockBase) for (const r of reqs) r.url = mockBase + '/src/' + r.source + '/' + encodeURIComponent(r.slug || r.source);
  return reqs;
}

// A single job link pasted in the chat: use the company's job-board feed when we know the board (the page itself
// is often built by JavaScript), otherwise read the page.
function manualRequests(url, mockBase) {
  const det = detectAts(url);
  const r = det && atsUrls()[det.ats]
    ? { source: det.ats, company: '', slug: det.slug, dream: false, url: atsUrls()[det.ats](det.slug), method: 'GET', manualUrl: url }
    : { source: 'manual', slug: url, url, method: 'GET', manualUrl: url };
  if (mockBase) r.url = mockBase + '/src/' + r.source + '/' + encodeURIComponent(r.slug || r.source);
  return [r];
}

// From a whole board, keep the one posting the link points at (matched on the posting id / path)
function pickManual(jobs, url) {
  const clean = (u) => String(u || '').toLowerCase().replace(/[?#].*$/, '').replace(/\/(apply|application)\/?$/, '').replace(/\/+$/, '');
  const target = clean(url);
  const id = (target.match(/([a-z0-9-]{6,})$/) || [])[1] || '';
  return jobs.find((j) => clean(j.url) === target || clean(j.applyUrl) === target)
    || (id ? jobs.find((j) => clean(j.url).endsWith(id) || clean(j.applyUrl).endsWith(id) || String(j.uid).endsWith(':' + id)) : null)
    || null;
}

function parseBody(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'object') return raw;
  const s = String(raw).trim();
  if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) { return null; } }
  if (/^(event|data):/m.test(s) && /^data:\s*\{/m.test(s)) { // MCP streamable-HTTP answered as server-sent events
    const datas = s.split('\n').filter((l) => l.startsWith('data:')).map((l) => l.slice(5).trim());
    for (const d of datas.reverse()) { try { return JSON.parse(d); } catch (e) {} }
  }
  return s; // XML / text
}

function rssItems(xml) {
  const items = [];
  const re = /<item>([\s\S]*?)<\/item>/g;
  let m;
  const tag = (block, t) => {
    const mm = block.match(new RegExp('<' + t + '[^>]*>([\\s\\S]*?)</' + t + '>'));
    if (!mm) return '';
    return mm[1].replace(/^<!\[CDATA\[/, '').replace(/\]\]>$/, '').trim();
  };
  while ((m = re.exec(xml))) {
    const b = m[1];
    items.push({ title: tag(b, 'title'), region: tag(b, 'region'), country: tag(b, 'country'), type: tag(b, 'type'),
      description: tag(b, 'description'), pubDate: tag(b, 'pubDate'), guid: tag(b, 'guid'), link: tag(b, 'link') });
  }
  return items;
}

function mk(job) {
  const company = (job.company || '').trim();
  const title = (job.title || '').trim();
  return Object.assign({
    location: '', remote: null, workplaceType: null, postedAt: null, url: '', applyUrl: '',
    salary: null, description: '', dream: false,
  }, job, {
    company, title,
    altKey: (company + '|' + title).toLowerCase().replace(/[^a-z0-9|]+/g, ' ').trim(),
    description: truncate(job.description || '', 12000),
  });
}

function normalize(req, raw) {
  const data = parseBody(raw);
  const out = [];
  const s = req.source;
  if (s === 'ashby' && data && data.jobs) {
    for (const j of data.jobs) {
      if (j.isListed === false) continue;
      const comp = j.compensation || {};
      out.push(mk({ uid: `ashby:${req.slug}:${j.id}`, source: s, sourceLabel: 'Ashby (direct)', company: req.company, dream: req.dream,
