  const msgs = [{ kind: 'tg_text', tg: { parse_mode: 'HTML', disable_web_page_preview: true, text: title + '\n\n' + reportLines(R).map(escHtml).join('\n') } }];
  if (R.pending.length) {
    const kb = [];
    for (const r of R.pending) {
